// kiban's LSM shape each second of its median 10M write run, through the drain
// that follows the last write (generated by scripts/bench-data.py).

import raw from "./tree-data.json";

/** [elapsed s, ops/s, files per level, MiB over level targets, flushes, compactions]. */
export type Sample = [
  number,
  number,
  [number, number, number, number],
  number,
  number,
  number,
];

const data = raw as unknown as {
  l0_stop: number;
  finish_s: number;
  rocksdb_finish_s: number;
  samples: Sample[];
};

export const samples = data.samples;
export const l0Stop = data.l0_stop;
export const finishS = data.finish_s;
export const rocksdbFinishS = data.rocksdb_finish_s;
export const endS = samples.at(-1)![0];
export const peakOps = Math.max(...samples.map((s) => s[1]));
export const peakDebt = Math.max(...samples.map((s) => s[3]));

const running = samples.filter((s) => s[0] <= finishS);
const stopped = running.filter((s) => s[1] === 0);
export const firstStop = stopped[0][0];
export const lastStop = stopped.at(-1)![0];
export const isStopped = (s: Sample) => s[0] <= finishS && s[1] === 0;

const fullStops = stopped.filter((s) => s[2][0] >= l0Stop).length;
const nearest = (t: number) =>
  samples.reduce((a, b) => (Math.abs(b[0] - t) < Math.abs(a[0] - t) ? b : a));

export function sampleAt(t: number) {
  let i = 0;
  while (i < samples.length - 1 && samples[i][0] < t) i++;
  return samples[i];
}

/** File counts between samples, so the drain moves instead of jumping. */
export function filesAt(t: number): [number, number, number, number] {
  let i = 0;
  while (i < samples.length - 1 && samples[i + 1][0] < t) i++;
  const a = samples[i];
  const b = samples[Math.min(i + 1, samples.length - 1)];
  const f =
    b[0] > a[0] ? Math.min(1, Math.max(0, (t - a[0]) / (b[0] - a[0]))) : 0;
  return a[2].map((n, level) => Math.round(n + (b[2][level] - n) * f)) as [
    number,
    number,
    number,
    number,
  ];
}

const at = (t: number) => nearest(t);
const STOP_WINDOW_S = 10;
const cluster = stopped.reduce((best, s) => {
  const inWindow = stopped.filter(
    (o) => o[0] >= s[0] && o[0] < s[0] + STOP_WINDOW_S,
  );
  return inWindow.length > best.length ? inWindow : best;
}, [] as Sample[]);
const firstFull = stopped.find((s) => s[2][0] >= l0Stop)!;
const clusterEnd = cluster.at(-1)!;
const secondsBehind = Math.round(finishS - rocksdbFinishS);

export type Stop = {
  t: number;
  title: string;
  body: string;
  active: 0 | 1 | 2 | 3;
  failure?: boolean;
};

// The moments worth stopping on, in run order. Every number is read from the
// samples above, and a failure stop lands exactly on a stopped second.
export const stops: Stop[] = [
  {
    t: 0,
    title: "one write run",
    body: "Four levels of a real tree, stacked. Scroll to open them.",
    active: 0,
  },
  {
    t: 0,
    title: "the tree",
    body: "Each flush lands in L0. Compaction moves files down through L1, L2 and L3.",
    active: 0,
  },
  {
    t: at(6)[0],
    title: "the tree fills",
    body: `Six seconds in, L0 holds ${at(6)[2][0]} files and ${at(6)[3]} MiB is already queued above level targets.`,
    active: 1,
  },
  {
    t: firstStop,
    title: "first stop",
    body: `No write completes this second. L0 is not full here: it holds ${stopped[0][2][0]} files, while L1 has grown to ${stopped[0][2][1]}.`,
    active: 0,
    failure: true,
  },
  {
    t: firstFull[0],
    title: "L0 is full",
    body: `L0 reaches its limit of ${l0Stop} files, and writers wait. ${fullStops} of the ${stopped.length} stopped seconds look like this one.`,
    active: 0,
    failure: true,
  },
  {
    t: clusterEnd[0],
    title: "the worst stretch",
    body: `${cluster.length} stopped seconds inside ${STOP_WINDOW_S} seconds. RocksDB finished this whole run at ${rocksdbFinishS.toFixed(0)} s.`,
    active: 0,
    failure: true,
  },
  {
    t: lastStop,
    title: "last stop",
    body: `The final stopped second of ${stopped.length}. ${at(lastStop)[3]} MiB is still queued above level targets.`,
    active: 0,
    failure: true,
  },
  {
    t: finishS,
    title: "last write",
    body: `All 10M writes done, ${secondsBehind} seconds behind RocksDB. L1 still holds ${at(finishS)[2][1]} files.`,
    active: 1,
  },
  {
    t: at(finishS + 2)[0],
    title: "the tree drains",
    body: `With writers gone, L1 falls to ${at(finishS + 2)[2][1]} files as L2 and L3 take them in.`,
    active: 2,
  },
  {
    t: endS,
    title: "settled",
    body: `L1 is empty and L3 holds ${samples.at(-1)![2][3]} files. The queue reaches zero ${(endS - finishS).toFixed(0)} seconds after the last write.`,
    active: 3,
  },
];
